    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 71-year-old male named Harold presents with slowly progressive, bilateral hearing loss. Rinne test is negative (BC > AC) bilaterally. Weber test does not lateralize. Audiogram shows a bilateral conductive hearing loss, with a specific drop in bone conduction thresholds at 2000 Hz (**Carhart''s notch**). Otoscopy is completely normal. What is the most likely diagnosis?', '["Cholesteatoma; a destructive, keratinizing epithelial lesion of the middle ear or mastoid cavity", "Otosclerosis; a metabolic bone disease characterized by abnormal bone remodeling of the otic capsule, leading to fixation of the stapes footplate", "Eustachian tube dysfunction; chronic negative middle ear pressure with retraction pocket and fluid accumulation", "Temporal arteritis; autoimmune vasculitis causing ischemia of the cochlea and stria vascularis", "Presbycusis; age-related sensorineural degeneration of the auditory nerve and sensory cochlear structures"]'::jsonb, 1, '**Otosclerosis** is a metabolic bone disease of the otic capsule characterized by abnormal bone resorption and deposition. It classically leads to **fixation of the stapes footplate** in the oval window, causing progressive conductive hearing loss. Key diagnostic features: (1) Bilateral conductive hearing loss (Rinne negative BC > AC), (2) Normal tympanic membrane (ruling out otitis media or cholesteatoma), and (3) **Carhart''s notch** (a characteristic artificial dip in bone conduction thresholds at 2000 Hz due to loss of the normal stapes resonance). While typically presenting in young adulthood, otosclerosis can progress or present in older adults. Treatment includes hearing aids or stapedectomy. (Ref: Hazzard''s Ch. 45; First Aid Step 2 CK)'),
